27	
28	/** Skills that legitimately carry no reference-formatting directive. */
29	const noRefDirective = new Set([
30	  // Owns the canonical blocks; pointing at itself would be circular.
31	  "shared-rules",
32	]);
33	
34	/**
35	 * A distinctive phrase from each relocated block. Presence in a consumer means the
36	 * inlined copy came back — matching on a phrase rather than the whole block catches
37	 * partial leftovers too.
38	 */
39	const removedBlockPhrases: Record<string, string> = {
40	  "reference-formatting": "Backticks suppress GitHub autolinking",
41	  "askuserquestion-format": "renders as raw text",
42	  "askuserquestion-contract": "Copy the full preview string literally into every option",
43	  "repomix-snapshot": "fall back to `mcp__repomix__pack_codebase` with",
44	  "issue-body-grammar": "each section answers exactly one question",
45	  "linear-mcp-access": "never bind a generic tool name",
46	  "peer-cli-delegation": "zero bytes of stdout",
47	  "pr-title-grammar": "Release keyword is required, capitalized exactly as shown",
48	  "pr-body-grammar": "DO NOT use `**Release Notes:**` (capital",
